//Execute45c210->45bec0 actual team gates; only cachedquery and terminaleffects recorded.
import ghidra.app.script.GhidraScript;import ghidra.app.emulator.EmulatorHelper;import java.io.*;
public class ZNov04ContactGateOracle extends GhidraScript{static final long RET=0x12345000L,S=0x7fff0000L,U=0x5e30c8L,V=U+192,R=0x60ec00L,W=0x1000000L;long read(EmulatorHelper e,long a,int n){byte[]b=e.readMemory(toAddr(a),n);long v=0;for(int i=0;i<n;i++)v|=(b[i]&255L)<<(8*i);return v;}void put(EmulatorHelper e,long a,int n,long v)throws Exception{e.writeMemoryValue(toAddr(a),n,v);}void back(EmulatorHelper e)throws Exception{long sp=e.readRegister("ESP").longValue(),ret=read(e,sp,4);e.writeRegister("ESP",sp+4);if(!e.run(toAddr(ret),null,monitor))throw new Exception(e.getLastError());}
 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){for(int mode=0;mode<2;mode++)for(int s=0;s<256;s++){EmulatorHelper e=new EmulatorHelper(currentProgram);try{e.writeMemory(toAddr(U),new byte[3*192]);e.writeMemory(toAddr(R),new byte[3*72]);e.writeMemory(toAddr(W),new byte[44]);e.writeMemory(toAddr(0x58aaaa),new byte[16384]);put(e,U+44,2,500);put(e,U+46,2,500);put(e,U+0x31,1,4+s%4);put(e,U+0x7c,1,1);put(e,U+0x10,4,32+32*128);put(e,U+8,4,W);put(e,W+7,1,80);put(e,V+44,2,520);put(e,V+46,2,520);put(e,V+0x31,1,4+s/4%4);put(e,V+0x7c,1,new int[]{0,3,1,2}[s/64%4]);put(e,V+0x35,1,1);put(e,V+0x5e,1,new int[]{255,1,0,2}[s/16%4]);put(e,V+0x5f,1,1);put(e,V+0x10,4,32+32*128);put(e,V+0x3a,1,30);put(e,R+72+19,1,1);put(e,0x632194,4,R+144);put(e,0x58aaaa+32+32*128,1,7);put(e,0x622dc0,1,0);put(e,0x622d54,4,0x27102710);put(e,0x622d58,4,0x27102710);
 for(long pc:new long[]{RET,0x44cd60,0x45bec0,0x45bd30,0x4525a0,0x458ec0})e.setBreakpoint(toAddr(pc));e.writeRegister("ESP",S);put(e,S,4,RET);e.writeRegister("ECX",mode==0?U:V);e.writeRegister("EDX",U);if(mode==1)e.clearBreakpoint(toAddr(0x45bec0));if(!e.run(toAddr(mode==0?0x45c210:0x45bec0),null,monitor))throw new Exception(e.getLastError());int gate=mode==1?1:0,delegate=0,route=0,n=0;while(e.readRegister("EIP").longValue()!=RET){if(++n>12)throw new Exception("budget");long pc=e.readRegister("EIP").longValue();if(pc==0x44cd60){put(e,0x62d3a8,1,1);put(e,0x62d3a9,1,255);back(e);}else if(pc==0x45bec0){gate++;e.clearBreakpoint(toAddr(pc));if(!e.run(toAddr(pc),null,monitor))throw new Exception(e.getLastError());}else if(pc==0x45bd30){delegate++;e.writeRegister("EAX",1);back(e);}else if(pc==0x4525a0){route++;back(e);}else throw new Exception("unexpected death");}out.println("{\"mode\":"+mode+",\"scenario\":"+s+",\"gate\":"+gate+",\"delegate\":"+delegate+",\"route\":"+route+",\"context\":"+((read(e,0x632194,4)-R)/72)+",\"flagsActor\":"+read(e,U+0x71,1)+",\"flagsPeer\":"+read(e,V+0x71,1)+"}");}finally{e.dispose();}}}}
}